rulesetGrouping.rbnfRules:
%spellout-numbering-year:
-x: mínus >>;
x.x: =0.0=;
0: =%spellout-numbering=;
1100/100: << $(cardinal,one{hundrað}other{hundruð})$[ >%%and-masculine>];
10000: =%spellout-numbering=;
%spellout-numbering:
0: =%spellout-cardinal-masculine=;
%spellout-cardinal-masculine:
-x: mínus >>;
x.x: << komma >>;
0: núll;
1: einn;
2: tveir;
3: þrír;
4: fjórir;
5: fimm;
6: sex;
7: sjö;
8: átta;
9: níu;
10: tíu;
11: ellefu;
12: tólf;
13: þrettán;
14: fjórtán;
15: fimmtán;
16: sextán;
17: sautján;
18: átján;
19: nítján;
20: tuttugu[ og >>];
30: þrjátíu[ og >>];
40: fjörutíu[ og >>];
50: fimmtíu[ og >>];
60: sextíu[ og >>];
70: sjötíu[ og >>];
80: áttatíu[ og >>];
90: níutíu[ og >>];
100: <%spellout-cardinal-neuter< $(cardinal,one{hundrað}other{hundruð})$[ >%%and-masculine>];
1000: <%spellout-cardinal-neuter< þúsund[ >%%and-masculine>];
1000000: ein milljón[ >%%and-masculine>];
2000000: <%spellout-cardinal-feminine< $(cardinal,one{milljón}other{milljónir})$[ >%%and-masculine>];
1000000000: einn milljarður[ >%%and-masculine>];
2000000000: <%spellout-cardinal-masculine< $(cardinal,one{milljarður}other{milljarðar})$[ >%%and-masculine>];
1000000000000: ein billjón[ >%%and-masculine>];
2000000000000: <%spellout-cardinal-feminine< $(cardinal,one{billjón}other{billjónir})$[ >%%and-masculine>];
1000000000000000: einn billjarður[ >%%and-masculine>];
2000000000000000: <%spellout-cardinal-masculine< $(cardinal,one{billjarður}other{billjarðar})$[ >%%and-masculine>];
1000000000000000000: =#,##0=;
