%%and-masculine:
1: og =%spellout-cardinal-masculine=;
20: [<%%tens< og >%spellout-cardinal-masculine>|og <%%tens<];
100: [<%spellout-cardinal-neuter< $(cardinal,one{hundrað}other{hundruð})$ >%%and-masculine>|og <%spellout-cardinal-neuter< $(cardinal,one{hundrað}other{hundruð})$];
1000: [<%spellout-cardinal-neuter< þúsund >%%and-masculine>|og <%spellout-cardinal-neuter< þúsund];
1000000: =%spellout-cardinal-masculine=;
%%and-neuter:
